const bayonGrid = `






























































































































































































































































































































































































`

pal({
  k: "#091b24",
  K: "#122f3b",
  T: "#1b4550",
  t: "#285f66",
  c: "#3d7a78",
  D: "#3d2e22",
  d: "#634b35",
  b: "#826649",
  s: "#a4825a",
  S: "#c9a36f",
  l: "#e8c589",
  L: "#fae0a2",
  O: "#e68e49",
  o: "#f0aa5f",
  a: "#f5c579",
  y: "#fae09b",
  w: "#fff7dc",
  m: "#d9e6c7",
  M: "#b8d3bc",
  h: "#93b8a3",
  H: "#6f9986",
  q: "#507c6a",
  F: "#1c4038",
  f: "#2e5e49",
  g: "#487f54",
  G: "#6fa464",
  e: "#8ec07a",
  u: "#66785f",
})

// Static 384x384 pixel-art base matching the reference image
sprite("_bayon_base", { w: 384, h: 384 }, bayonGrid)

// Gliding white birds in the misty valley (8 frames, 800ms loop)
anim("_bird", { w: 9, h: 5, frames: 8, fps: 10 }, (c) => {
  const flap = Math.round(Math.sin(c.phase * Math.PI * 2) * 1.4)
  c.line(1, 2 + flap, 4, 2, "w")
  c.line(4, 2, 7, 2 + flap, "w")
  c.px(4, 3, "m")
})

// Subtle golden sunbeams / pulsing sun halo + floating golden dust motes (8 frames)
anim("_atmosphere", { w: 384, h: 384, frames: 8, fps: 10 }, (c) => {
  // Subtle pulsing sun edge
  if (c.frame % 4 < 2) {
    c.ring(338, 34, 17, "y")
  }
  // Floating golden dust motes & fireflies
  const motes = [
    [195, 110], [235, 160], [270, 130], [175, 225],
    [255, 250], [72, 155], [310, 200], [210, 68],
    [130, 190], [290, 280], [340, 240],
  ]
  for (let i = 0; i < motes.length; i++) {
    const [bx, by] = motes[i]
    const dx = Math.round(Math.sin(c.phase * Math.PI * 2 + i) * 4)
    const dy = Math.round(Math.cos(c.phase * Math.PI * 2 + i * 1.5) * 3)
    const col = (c.frame + i) % 4 < 2 ? "w" : "y"
    c.rect(bx + dx, by + dy, 2, 2, col)
  }
})

// Gentle wind shimmer on foreground grass (bottom-right)
anim("_grass_wind", { w: 60, h: 48, frames: 8, fps: 10 }, (c) => {
  const sway = Math.round(Math.sin(c.phase * Math.PI * 2) * 2)
  for (let i = 0; i < 8; i++) {
    const x = 6 + i * 7
    const h = 18 + (i % 3) * 8
    c.line(x, 47, x + sway, 47 - h, i % 2 === 0 ? "e" : "G")
  }
})

// Final 384x384 animated scene (upscaled 2x -> 768x768)
scene("bayon", { w: 384, h: 384 },
  layer("base", stamp("_bayon_base", 0, 0)),
  layer("birds",
    stamp("_bird", 285, 290),
    stamp("_bird", 315, 275, { delay: 200 }),
    stamp("_bird", 232, 176, { delay: 400 })
  ),
  layer("grass_wind", stamp("_grass_wind", 324, 336)),
  layer("atmosphere", stamp("_atmosphere", 0, 0)),
  glow("w", { r: 14, strength: 0.35, where: (x, y) => x > 300 && y < 75 })
)

